import {newGame} from './simulation.js';
import {startSurvival,finishSurvivalDay} from './survival-base.js';
import {moveSurvivalPartyMember,createSurvivalParty,dispatchSurvivalParty} from './survival-parties.js';
export function partyDelayCampaign(base){let s=structuredClone(base??newGame());delete s.survivalRun;delete s.combatTrial;s=startSurvival(s,'solo',{seed:6});Object.assign(s.survivalRun,{day:4,stage:'base',base:{site:'basement',integrity:95,exposure:0,facilities:['annex','barricade']},resources:{food:60,water:60,parts:8,bandage:6},threat:60});for(let i=1;i<6;i++)s.survivalRun.members.push({...structuredClone(s.survivalRun.members[0]),key:'member-'+i,label:['','한서연','보급팀 학생 1','보급팀 학생 2','지원팀 학생 1','지원팀 학생 2'][i],character:i===1?'seoyeon':'student',partyConsent:true,fatigue:10,stress:15,injury:0,nutrition:85,hydration:85,attributes:{strength:4,agility:4,vitality:4,endurance:4,mentality:4}});s=moveSurvivalPartyMember(s,'member-1','party-1');s=createSurvivalParty(s,'member-2','편의점 보급팀');s=moveSurvivalPartyMember(s,'member-3','party-2');s=createSurvivalParty(s,'member-4','지원 파티');s=moveSurvivalPartyMember(s,'member-5','party-3');s.survivalRun.parties.bonds['member:member-4']={familiarity:30,trust:25,affection:10,tension:0};return s;}
export function delayedPartyCampaign(base){return finishSurvivalDay(dispatchSurvivalParty(partyDelayCampaign(base),'party-2','supply'));}
export const partyRescueRoute=Array.from({length:4},()=>[['taei','guard'],['end']]).flat();
